 * Runs an instant-runoff count over a parsed election, one round at a time,
 * eliminating the candidate with the fewest votes until a majority is
 * reached or every ballot is exhausted.
 */

/**
 * @param {string[]} candidates declared candidate names
 * @param {{ count: number, choices: string[] }[]} ballots
 * @returns {{ rounds: { votes: Map<string, number>, exhausted: number, eliminated: string|null }[], winner: string|null }}
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const roundsHistory = []
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.choices.find((name) => continuing.has(name))
      if (choice !== undefined) {
        votes.set(choice, votes.get(choice) + ballot.count)
      } else {
        exhausted += ballot.count
      }
    }

    roundsHistory.push(votes)

    let activeTotal = 0
    for (const v of votes.values()) activeTotal += v

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = null
      break
    }

    let majorityWinner = null
    for (const [name, v] of votes) {
      if (v * 2 > activeTotal) {
        majorityWinner = name
        break
      }
    }

    if (majorityWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = majorityWinner
      break
    }

    const minVotes = Math.min(...votes.values())
    const tied = [...votes.keys()].filter((name) => votes.get(name) === minVotes)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, roundsHistory)

    rounds.push({ votes, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/**
 * Resolves a tie for fewest votes by comparing the tied candidates' vote
 * counts round by round, starting from round one, narrowing to whichever
 * survivors had the fewest votes at the first round that separates them and
 * restarting the comparison from round one. A tie with no separating round
 * is broken by picking the name that sorts last by code point.
 */
function breakTie(tiedNames, roundsHistory) {
  let survivors = tiedNames
  let roundIndex = 0

  while (roundIndex < roundsHistory.length) {
    const round = roundsHistory[roundIndex]
    const values = survivors.map((name) => round.get(name))
    const allEqual = values.every((v) => v === values[0])

    if (!allEqual) {
      const min = Math.min(...values)
      survivors = survivors.filter((name) => round.get(name) === min)
      if (survivors.length === 1) return survivors[0]
      roundIndex = 0
      continue
    }

    roundIndex++
  }

  return survivors.slice().sort().at(-1)
}
"}

