 * Renders the outcome of a completed count into the `rounds` or `tally`
 * output formats.
 */

function sortedEntries(votes) {
  return [...votes.entries()].sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
}

function winnerLine(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}

export function formatRounds({ rounds, winner }) {
  const lines = []
  rounds.forEach((round, index) => {
    const entries = sortedEntries(round.votes).map(([name, v]) => `${name}=${v}`)
    lines.push(`round ${index + 1}: ${entries.join(' ')} exhausted=${round.exhausted}`)
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(winnerLine(winner))
  return lines.join('\n') + '\n'
}

export function formatTally({ rounds, winner }) {
  return `rounds ${rounds.length}\n${winnerLine(winner)}\n`
}
